export type ParsedInitializeMarketplaceInstruction<
  TProgram extends string = typeof KATHA_MARKETPLACE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    config: TAccountMetas[0];
    bootstrapAuthority: TAccountMetas[1];
    program: TAccountMetas[2];
    programData: TAccountMetas[3];
    registryProgram: TAccountMetas[4];
    registryConfig: TAccountMetas[5];
    authority: TAccountMetas[6];
    paymentMint: TAccountMetas[7];
    tokenProgram: TAccountMetas[8];
    systemProgram: TAccountMetas[9];
  };
  data: InitializeMarketplaceInstructionData;
};

export function parseInitializeMarketplaceInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedInitializeMarketplaceInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 10,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      config: getNextAccount(),
      bootstrapAuthority: getNextAccount(),
      program: getNextAccount(),
      programData: getNextAccount(),
      registryProgram: getNextAccount(),
      registryConfig: getNextAccount(),
      authority: getNextAccount(),
      paymentMint: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getInitializeMarketplaceInstructionDataDecoder().decode(instruction.data),
  };
}
